"""
logging_service.py - Generischer Logging-Handler zum Schreiben von Python-Logs in MariaDB.

Verwendung:
    import logging

    from core_services.db import setup_database_logging

    logging.basicConfig(
        level=logging.INFO,
        format="%(asctime)s %(levelname)s %(name)s - %(message)s",
        force=True,
    )
    setup_database_logging(logger_name=__name__, level="INFO", auto_create=True)

    logger = logging.getLogger(__name__)
    logger.info("Diese Meldung wird in die DB geschrieben.")

Hinweis:
    Wenn logging.basicConfig(..., force=True) verwendet wird, muss
    setup_database_logging() danach aufgerufen werden, weil force=True
    vorher registrierte Handler entfernt.

Tabellenschema:
    CREATE TABLE IF NOT EXISTS tb_python_log (
        id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT 'Eindeutige technische ID des Logeintrags',
        created_at DATETIME NOT NULL COMMENT 'Zeitpunkt, zu dem der LogRecord erzeugt wurde',
        level_name VARCHAR(20) NOT NULL COMMENT 'Logging-Level, z.B. DEBUG, INFO, WARNING oder ERROR',
        logger_name VARCHAR(255) NOT NULL COMMENT 'Name des Python-Loggers',
        module VARCHAR(255) NULL COMMENT 'Python-Modul, aus dem der Logeintrag kommt',
        function_name VARCHAR(255) NULL COMMENT 'Funktion oder Methode, aus der der Logeintrag kommt',
        line_no INT NULL COMMENT 'Zeilennummer im Python-Code',
        message TEXT NOT NULL COMMENT 'Formatierte Logmeldung',
        exception_text MEDIUMTEXT NULL COMMENT 'Stacktrace bei Logs mit exc_info=True',
        process_id INT NULL COMMENT 'Betriebssystem-Prozess-ID',
        thread_name VARCHAR(255) NULL COMMENT 'Name des Python-Threads'
    );
"""

from __future__ import annotations

import logging
import threading
import traceback
from datetime import datetime
from typing import Any

from ..constants import DATABASE
from .db_service import execute_sql_query

LOG_TABLE = "tb_python_log"
QUOTED_LOG_TABLE = "`tb_python_log`"

CREATE_LOG_TABLE_SQL = f"""
    CREATE TABLE IF NOT EXISTS {QUOTED_LOG_TABLE} (
        id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT 'Eindeutige technische ID des Logeintrags',
        created_at DATETIME NOT NULL COMMENT 'Zeitpunkt, zu dem der LogRecord erzeugt wurde',
        level_name VARCHAR(20) NOT NULL COMMENT 'Logging-Level, z.B. DEBUG, INFO, WARNING oder ERROR',
        logger_name VARCHAR(255) NOT NULL COMMENT 'Name des Python-Loggers',
        module VARCHAR(255) NULL COMMENT 'Python-Modul, aus dem der Logeintrag kommt',
        function_name VARCHAR(255) NULL COMMENT 'Funktion oder Methode, aus der der Logeintrag kommt',
        line_no INT NULL COMMENT 'Zeilennummer im Python-Code',
        message TEXT NOT NULL COMMENT 'Formatierte Logmeldung',
        exception_text MEDIUMTEXT NULL COMMENT 'Stacktrace bei Logs mit exc_info=True',
        process_id INT NULL COMMENT 'Betriebssystem-Prozess-ID',
        thread_name VARCHAR(255) NULL COMMENT 'Name des Python-Threads'
    )
"""

INSERT_LOG_RECORD_SQL = f"""
    INSERT INTO {QUOTED_LOG_TABLE} (
        created_at,
        level_name,
        logger_name,
        module,
        function_name,
        line_no,
        message,
        exception_text,
        process_id,
        thread_name
    )
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
"""


class DatabaseLogHandler(logging.Handler):
    """Schreibt LogRecords in eine MariaDB-tabelle."""

    def __init__(
        self,
        database: str = DATABASE,
        level: int | str = logging.INFO,
        auto_create: bool = False,
    ) -> None:
        """Initialisiert den Handler und legt die tabelle optional an."""
        super().__init__(level=_coerce_level(level))
        self.table_name = LOG_TABLE
        self.database = database
        self._local = threading.local()
        if auto_create:
            self.ensure_table()

    def ensure_table(self) -> None:
        """Legt die Log-tabelle an, falls sie noch nicht existiert."""
        execute_sql_query(CREATE_LOG_TABLE_SQL, database=self.database)

    def emit(self, record: logging.LogRecord) -> None:
        """Schreibt einen einzelnen LogRecord in die Datenbank."""
        if getattr(self._local, "active", False):
            return

        self._local.active = True
        try:
            exception_text = None
            if record.exc_info:
                exception_text = "".join(traceback.format_exception(*record.exc_info))

            values: tuple[Any, ...] = (
                datetime.fromtimestamp(record.created),
                record.levelname,
                record.name,
                record.module,
                record.funcName,
                record.lineno,
                self.format(record),
                exception_text,
                record.process,
                record.threadName,
            )

            execute_sql_query(INSERT_LOG_RECORD_SQL, params=values, database=self.database)
        except Exception:
            self.handleError(record)
        finally:
            self._local.active = False


def setup_database_logging(
    logger_name: str | None = None,
    database: str = DATABASE,
    level: int | str = logging.INFO,
    auto_create: bool = False,
) -> DatabaseLogHandler:
    """Haengt einen DB-Logging-Handler an einen Logger.

    Args:
        logger_name: Name des Loggers. ``None`` konfiguriert den Root-Logger.
        database: Datenbankname.
        level: Minimales Log-Level fuer den Handler.
        auto_create: Legt die tabelle automatisch an, wenn sie fehlt.

    Returns:
        Der angelegte oder bereits vorhandene DatabaseLogHandler.
    """
    target_logger = logging.getLogger(logger_name)
    numeric_level = _coerce_level(level)

    for handler in target_logger.handlers:
        if isinstance(handler, DatabaseLogHandler) and handler.database == database:
            handler.setLevel(numeric_level)
            return handler

    handler = DatabaseLogHandler(
        database=database,
        level=numeric_level,
        auto_create=auto_create,
    )
    handler.setFormatter(logging.Formatter("%(message)s"))
    target_logger.addHandler(handler)
    target_logger.setLevel(min(target_logger.level or numeric_level, numeric_level))
    return handler


def _coerce_level(level: int | str) -> int:
    """Wandelt Level-Namen wie 'INFO' in logging-Levelnummern um."""
    if isinstance(level, int):
        return level

    numeric_level = getattr(logging, level.upper(), None)
    if not isinstance(numeric_level, int):
        raise ValueError(f"Ungueltiges Log-Level: {level}")
    return numeric_level
